"},{"src/App.css":"/* Reset and Base Styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary-color: #6c63ff;
  --secondary-color: #f8f9fa;
  --text-color: #333;
  --light-text-color: #666;
  --bg-color: #fff;
  --card-bg-color: #f8f9fa;
  --shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  --border-radius: 8px;
  --transition: all 0.3s ease;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  line-height: 1.6;
  color: var(--text-color);
  background-color: var(--bg-color);
}

/* Portfolio Container */
.portfolio-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Hero Section */
.hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 80px 0;
  gap: 40px;
}

.hero-content {
  flex: 1;
  max-width: 600px;
}

.hero h1 {
  font-size: 3rem;
  margin-bottom: 10px;
  line-height: 1.2;
}

.highlight {
  color: var(--primary-color);
}

.hero-subtitle {
  font-size: 1.5rem;
  color: var(--light-text-color);
  margin-bottom: 20px;
}

.hero-description {
  margin-bottom: 30px;
  color: var(--light-text-color);
}

.cta-button {
  display: inline-block;
  padding: 12px 24px;
  background-color: var(--primary-color);
  color: white;
  text-decoration: none;
  border-radius: var(--border-radius);
  font-weight: 600;
  transition: var(--transition);
}

.cta-button:hover {
  background-color: #5a52d5;
  transform: translateY(-2px);
}

.hero-image {
  flex: 1;
  text-align: center;
}

.hero-image img {
  max-width: 100%;
  border-radius: var(--border-radius);
  box-shadow: var(--shadow);
}

/* About Section */
.about {
  padding: 60px 0;
  text-align: center;
}

.about h2 {
  font-size: 2.5rem;
  margin-bottom: 20px;
}

.about-content {
  max-width: 800px;
  margin: 0 auto;
}

.about-content p {
  margin-bottom: 15px;
  color: var(--light-text-color);
}

/* Skills Section */
.skills {
  padding: 60px 0;
  text-align: center;
}

.skills h2 {
  font-size: 2.5rem;
  margin-bottom: 40px;
}

.skills-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
}

.skill-card {
  background-color: var(--card-bg-color);
  padding: 20px;
  border-radius: var(--border-radius);
  box-shadow: var(--shadow);
  transition: var(--transition);
}

.skill-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.15);
}

.skill-card h3 {
  font-size: 1.5rem;
  margin-bottom: 10px;
  color: var(--primary-color);
}

.skill-card p {
  color: var(--light-text-color);
}

/* Projects Section */
.projects {
  padding: 60px 0;
  text-align: center;
}

.projects h2 {
  font-size: 2.5rem;
  margin-bottom: 40px;
}

.projects-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 30px;
}

.project-card {
  background-color: var(--card-bg-color);
  border-radius: var(--border-radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: var(--transition);
}

.project-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.15);
}

.project-card img {
  width: 100%;
  height: 200px;
  object-fit: cover;
}

.project-card h3 {
  padding: 15px 20px 10px;
  font-size: 1.3rem;
}

.project-card p {
  padding: 0 20px 15px;
  color: var(--light-text-color);
}

.project-links {
  display: flex;
  justify-content: center;
  gap: 15px;
  padding: 0 20px 20px;
}

.project-link {
  display: inline-block;
  padding: 8px 16px;
  background-color: var(--primary-color);
  color: white;
  text-decoration: none;
  border-radius: var(--border-radius);
  font-size: 0.9rem;
  transition: var(--transition);
}

.project-link:hover {
  background-color: #5a52d5;
}

/* Contact Section */
.contact {
  padding: 60px 0;
  text-align: center;
}

.contact h2 {
  font-size: 2.5rem;
  margin-bottom: 20px;
}

.contact-content {
  max-width: 600px;
